 require('dotenv').config();
const colors = require('chromium');

const driver = await chromium.create();
await driver.get('http://example.com');

let blueSquares = 0;
let elements = await driver.evaluate(() => {
  return document.querySelectorAll('img');
});

for (let i = 0; i < elements.length; i++) {
  if (colors.getPixelColor(elements[i].getSrcElement(), 0, 0)) {
    blueSquares++;
  }
}

await driver.close();

console.log(JSON.stringify({ count: blueSquares }));



